#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long min_p = 2e18, max_profit = 0;
    for (int i = 0; i < n; i++) {
        long long p; scanf("%lld", &p);
        if (p < min_p) min_p = p;
        else if (p - min_p > max_profit) max_profit = p - min_p;
    }
    printf("%lld\n", max_profit);
    return 0;
}

code.C++:
#include <iostream>
#include <algorithm>
using namespace std;
int main() {
    int n; if (cin >> n) {
        long long min_p = 2e18, max_profit = 0;
        for (int i = 0; i < n; i++) {
            long long p; cin >> p;
            min_p = min(min_p, p);
            max_profit = max(max_profit, p - min_p);
        }
        cout << max_profit << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long minP = Long.MAX_VALUE, maxProfit = 0;
            for (int i = 0; i < n; i++) {
                long p = sc.nextLong();
                minP = Math.min(minP, p);
                maxProfit = Math.max(maxProfit, p - minP);
            }
            System.out.println(maxProfit);
        }
    }
}

